package com.nexus500m.app

import com.nexus500m.app.model.BpeTokenizer
import com.nexus500m.app.model.NexusFormat
import com.nexus500m.app.agent.Tools
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * GOLDEN PARITY TEST: the Kotlin on-device engine must reproduce exactly what
 * the Python training side produced for the SAME int8-quantized checkpoint.
 *
 * golden.json is generated by nexus/generate.py from the exported .nexus file;
 * both files are committed together, so this test is the hard contract between
 * the training pipeline and the phone.
 */
class InferenceGoldenTest {

    companion object {
        private val modelFile = File(javaClass.classLoader!!.getResource("nexus-demo-v0.1.0.nexus")!!.file)
        private val golden = JSONObject(
            javaClass.classLoader!!.getResourceAsStream("golden.json")!!
                .readBytes().toString(Charsets.UTF_8)
        )
    }

    private fun loadEngine() = com.nexus500m.app.model.InferenceEngine.load(modelFile)

    @Test
    fun modelLoadsAndReportsHonestMetadata() {
        val engine = loadEngine()
        assertEquals("nexus-demo", engine.info.modelName)
        assertEquals("0.1.0", engine.info.modelVersion)
        assertTrue("model must have parameters", engine.info.parameterCount > 0)
        assertTrue("integrity fingerprint present", engine.info.weightsSha256.length == 64)
    }

    @Test
    fun tokenizerMatchesPythonTokenIds() {
        val engine = loadEngine()
        val expected = golden.getJSONArray("prompt_token_ids")
        // golden stores ints; compare with Kotlin encoding of the same prompt
        val prompt = golden.getString("prompt")
        val encoded = engine.tokenizer.encode(prompt)
        assertEquals("prompt token count differs", expected.length(), encoded.size)
        for (i in 0 until expected.length()) {
            assertEquals("token $i differs", expected.getInt(i), encoded[i])
        }
    }

    @Test
    fun tokenizerRoundTrip() {
        val engine = loadEngine()
        val samples = listOf(
            "Hello, World! def add(a, b): return a + b",
            "### Instruction:\nWrite a note.\n### Response:\n",
            "tabs\tand\nnewlines 123 @#\$%",
        )
        for (s in samples) {
            val ids = engine.tokenizer.encode(s)
            assertEquals(s, engine.tokenizer.decode(ids))
        }
    }

    @Test
    fun firstStepLogitsMatchPythonWithinTolerance() {
        val engine = loadEngine()
        val prompt = golden.getString("prompt")
        val ids = engine.tokenizer.encode(prompt)
        val logits = engine.lastPositionLogits(ids)

        val expectedArr = golden.getJSONArray("first_step_logits")
        var maxDiff = 0.0
        for (i in 0 until expectedArr.length()) {
            maxDiff = maxOf(maxDiff, kotlin.math.abs(logits[i].toDouble() - expectedArr.getDouble(i)))
        }
        // int8-quantized weights reloaded on two runtimes: tiny float differences
        // are expected, but they must stay small.
        assertTrue("max logit diff $maxDiff exceeds tolerance", maxDiff < 0.5)
    }

    @Test
    fun greedyContinuationMatchesPython() {
        val engine = loadEngine()
        val prompt = golden.getString("prompt")
        val expectedArr = golden.getJSONArray("sampled_token_ids")
        val continuation = engine.generate(
            prompt = prompt,
            maxNewTokens = expectedArr.length(),
            temperature = 0f,     // greedy, same as Python golden generation
        )
        val produced = engine.tokenizer.encode(prompt + continuation).toList()
        val promptIds = engine.tokenizer.encode(prompt).toList()
        val sampled = produced.subList(promptIds.size, produced.size)
        // Compare prefix: continue while ids match (near-ties could truncate the tail)
        var matched = 0
        for (i in 0 until minOf(sampled.size, expectedArr.length())) {
            if (sampled[i] == expectedArr.getInt(i)) matched++ else break
        }
        assertTrue(
            "greedy continuation diverged after $matched/${expectedArr.length()} tokens",
            matched >= minOf(8, expectedArr.length()),
        )
    }

    @Test
    fun corruptedModelIsRejected() {
        // tamper with a copy: integrity check must refuse to load it
        val tampered = File.createTempFile("tampered", ".nexus")
        modelFile.copyTo(tampered, overwrite = true)
        // flip a byte inside weights.bin area near the end
        val raf = java.io.RandomAccessFile(tampered, "rw")
        raf.seek(raf.length() / 2)
        val b = raf.read()
        raf.seek(raf.length() / 2)
        raf.write(b.toInt() xor 0xFF)
        raf.close()
        var threw = false
        try {
            NexusFormat.load(tampered)
        } catch (t: Throwable) {
            threw = true
        }
        assertTrue("tampered model must be rejected", threw)
        tampered.delete()
    }
}

class ToolsTest {

    @Test
    fun calculatorHandlesRealExpressions() {
        assertEquals(110.0, Tools.evaluateExpression("25 * 4 + 10"), 1e-9)   // 25*4=100, +10
        assertEquals(60.0, Tools.evaluateExpression("(12 + 8) * 3"), 1e-9)
        assertEquals(-5.0, Tools.evaluateExpression("-2 - 3"), 1e-9)
        assertEquals(2.5, Tools.evaluateExpression("5 / 2"), 1e-9)
        assertEquals(1.0, Tools.evaluateExpression("7 % 2"), 1e-9)
    }

    @Test
    fun calculatorRejectsGarbageSafely() {
        listOf("delete files", "import os", "2 +", "()").forEach { expr ->
            val r = Tools.calculate(expr)
            assertFalse("must reject: $expr", r.success)
        }
    }

    @Test
    fun sensitiveTextIsRefusedAsMemory() {
        assertTrue(Tools.looksSensitive("my password = hunter2"))
        assertTrue(Tools.looksSensitive("github_pat_11ABCDEFGH0123456789_abcdefghijklmnopqrstuvwxyz123"))
        assertTrue(Tools.looksSensitive("-----BEGIN RSA PRIVATE KEY-----"))
        assertFalse(Tools.looksSensitive("my favorite project is nexus-500m"))
    }
}
